INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '填空', 1, '{"stem": "看图填空（图意：图中一共20个苹果，每5个苹果圈成1份）：共有这样的（　）份，表示（　）的（　）倍。", "options": null}', '4；5；4', '20个苹果每5个1份，20÷5=4，共有4份；每份5个，表示5的4倍。算式：5×4=20（或4×5=20）。', 'paper', '["practice", "ykl3sx", "4.7"]', '["paper_png/ykl3_sx/p080.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '填空', 1, '{"stem": "看图填空（图意：图中一共24根小棒，每3根小棒圈成1份）：共有这样的（　）份，表示（　）的（　）倍。", "options": null}', '8；3；8', '24根小棒每3根1份，24÷3=8，共有8份；每份3根，表示3的8倍。算式：3×8=24（或8×3=24）。', 'paper', '["practice", "ykl3sx", "4.7"]', '["paper_png/ykl3_sx/p080.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '填空', 1, '{"stem": "看图填空（图意：图中梨每2个圈成1份，一共圈了5份）：梨共有（　）个，表示（　）的（　）倍。", "options": null}', '10；2；5', '每份2个，共5份：2×5=10（个），梨有10个，表示2的5倍。算式：2×5=10（或5×2=10）。', 'paper', '["practice", "ykl3sx", "4.7"]', '["paper_png/ykl3_sx/p080.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '填空', 1, '{"stem": "看图填空（图意：图中12只小鸭，每6只圈成1份）：共有这样的（　）份，表示（　）的（　）倍。", "options": null}', '2；6；2', '12只小鸭每6只1份，12÷6=2，共有2份；每份6只，表示6的2倍。算式：6×2=12（或2×6=12）。', 'paper', '["practice", "ykl3sx", "4.7"]', '["paper_png/ykl3_sx/p080.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '填空', 2, '{"stem": "42×2=（　），表示（　）个42的和，也就是42的（　）倍。", "options": null}', '84；2；2', '42×2表示2个42相加：42+42=84；几个几用乘法表示，2个42就是42的2倍，42×2=84。', 'paper', '["practice", "ykl3sx", "4.7"]', '["paper_png/ykl3_sx/p081.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '填空', 2, '{"stem": "53+53+53+53=（　）×（　）=（　），表示（　）个53的和。", "options": null}', '53；4；212；4', '4个53连加，可以写成乘法53×4=212（先算50×4=200，3×4=12，200+12=212），表示4个53的和。', 'paper', '["practice", "ykl3sx", "4.7"]', '["paper_png/ykl3_sx/p081.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '填空', 1, '{"stem": "连一连：25+25+25+25表示（　）。", "options": null}', '25的4倍（4个25）', '4个25连加就是25×4，表示4个25相加，也就是25的4倍。', 'paper', '["practice", "ykl3sx", "4.7"]', '["paper_png/ykl3_sx/p081.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
