INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '填空', 2, '{"stem": "连一连：16+16+16+16+8+8表示（　）。", "options": null}', '16的5倍', '8+8=16，原式就是16+16+16+16+16，即5个16相加，表示16的5倍。', 'paper', '["practice", "ykl3sx", "4.7"]', '["paper_png/ykl3_sx/p081.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1031, '数学', '三年级', '应用题', 2, '{"stem": "小华和小海在图书馆各自借了一本书，第一天他们都看了32页。第二天，小华看的页数是第一天的2倍，小海看的页数是第一天的3倍。小华第二天看了（　）页，小海一共看了（　）页。", "options": null}', '64；96', '求一个数的几倍是多少用乘法。小华第二天看32×2=64（页）；小海一共看的是第一天的3倍：32×3=96（页）。', 'paper', '["practice", "ykl3sx", "4.7"]', '["paper_png/ykl3_sx/p081.png"]', 0);
